def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 18.0))

    serious_bids = []
    cindy_bid = None
    danger_count = 0
    weak_count = 0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = None
        if prev:
            pbid = prev.get('bid')
        if pbid is not None:
            serious_bids.append(float(pbid))
            if oid == 'Cindy':
                cindy_bid = float(pbid)
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            danger_count += 1
        if opp.get('budget', 0) < 25:
            weak_count += 1

    units = supply / float(WATER_REQ)

    if hp <= 1 or no_water >= 2:
        emergency = 68.0
        if cindy_bid is not None:
            emergency = max(emergency, min(95.0, cindy_bid + 4.0))
        return float(min(budget, emergency))

    if hp <= 2 or no_water >= 1:
        urgent = 54.0
        if cindy_bid is not None:
            urgent = max(urgent, min(90.0, cindy_bid + 2.0))
        elif serious_bids:
            urgent = max(urgent, min(85.0, max(serious_bids) + 2.0))
        return float(min(budget, urgent))

    if units >= 2.0:
        base = 16.0
        if cindy_bid is not None:
            if cindy_bid >= 90:
                base = 12.0
            elif cindy_bid >= 70:
                base = 18.0
            else:
                base = 22.0
        elif serious_bids:
            mx = max(serious_bids)
            if mx >= 80:
                base = 14.0
            elif mx >= 40:
                base = 20.0
            else:
                base = 24.0
        if weak_count >= 2:
            base -= 2.0
        if day >= 8:
            base += 4.0
        return float(min(budget, max(8.0, base)))

    base = 34.0
    if cindy_bid is not None:
        if cindy_bid >= 95:
            base = 28.0
        elif cindy_bid >= 80:
            base = 36.0
        elif cindy_bid >= 60:
            base = 42.0
        else:
            base = 38.0
    elif serious_bids:
        mx = max(serious_bids)
        base = max(32.0, min(48.0, mx + 1.5))

    if danger_count >= 2:
        base += 6.0
    if day >= 8:
        base += 8.0
    if budget < 60:
        base -= 4.0

    return float(min(budget, max(18.0, base)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    alex_status = opponents_status.get('Alex')

    base_bid = DAILY_SALARY * 0.5 

    if my_status['hp'] <= 2: 
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4: 
        base_bid = DAILY_SALARY * 0.8
    elif my_status['no_water_days'] > 0: 
        base_bid = DAILY_SALARY * 0.85

    num_players_can_be_satisfied = day_context['supply'] // WATER_REQ

    if num_players_can_be_satisfied < len(alive_opponents) + 1: 
        base_bid = max(base_bid, DAILY_SALARY * 0.6) 
        if day_context['supply'] < WATER_REQ * 1.5: 
             base_bid = max(base_bid, DAILY_SALARY * 0.75)

    alex_prev_bid = 0
    if alex_status and alex_status.get('previous_trace'):
        alex_prev_bid = alex_status['previous_trace'].get('bid', 0)

        if alex_prev_bid > DAILY_SALARY * 0.6:
            if my_status['hp'] <= 5:
                base_bid = max(base_bid, alex_prev_bid * 1.05) 
            else:
                base_bid = max(base_bid, alex_prev_bid * 0.9) 
        elif alex_prev_bid > 0 and alex_prev_bid < DAILY_SALARY * 0.4:
            base_bid = min(base_bid, max(DAILY_SALARY * 0.4, alex_prev_bid + 5))

    if day_context['day'] >= EPISODE_DAYS - 2: 
        if my_status['hp'] <= 5: 
            base_bid = DAILY_SALARY * 0.9
        else: 
            base_bid = max(base_bid, DAILY_SALARY * 0.6)

    final_bid = min(my_status['budget'], base_bid)

    if my_status['hp'] <= 1 and my_status['budget'] > 0:
        final_bid = my_status['budget']

    if final_bid < 10 and my_status['budget'] > 0 and my_status['hp'] > 2:
        final_bid = min(my_status['budget'], 15)

    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 4:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    bid = avg_prev_bid + 2.0
    return min(my_status['budget'], max(bid, DAILY_SALARY * 0.4))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive_opps = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opps)

    prev_bids = []
    for opp in alive_opps:
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.85
    elif my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.7
    else:
        if prev_bids and max(prev_bids) > 100:
            base_bid = DAILY_SALARY * 0.25
        else:
            base_bid = DAILY_SALARY * 0.5

    supply = day_context['supply']
    supply_factor = 1 + ((MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)) * 0.3
    bid = base_bid * supply_factor
    bid = min(bid, my_status['budget'])
    bid = max(bid, 0)
    return round(bid, 2)
